void zmpopGenericCommand(client *c, int numkeys_idx, int is_block) {
    zset_exec.m_zmpopGenericCommand_c = c;
    zset_exec.m_zmpopGenericCommand_numkeys_idx = numkeys_idx;
    zset_exec.m_zmpopGenericCommand_is_block = is_block;
